  assert.equal(result.ok, true);
  assert.equal(result.value, 201);
});

test('formatMoney EUR with default currency', () => {
  assert.equal(formatMoney(123456, 'EUR'), '€1,234.56');
});

test('formatMoney USD', () => {
  assert.equal(formatMoney(123456, 'USD'), '$1,234.56');
});

test('formatMoney GBP', () => {
  assert.equal(formatMoney(123456, 'GBP'), '£1,234.56');
});

test('formatMoney with negative amount', () => {
  assert.equal(formatMoney(-250, 'USD'), '-$2.50');
  assert.equal(formatMoney(-250, 'GBP'), '-£2.50');
  assert.equal(formatMoney(-250, 'EUR'), '-€2.50');
});

test('formatMoney with zero', () => {
  assert.equal(formatMoney(0, 'USD'), '$0.00');
  assert.equal(formatMoney(0, 'GBP'), '£0.00');
  assert.equal(formatMoney(0, 'EUR'), '€0.00');
});

test('formatMoney with small amount', () => {
  assert.equal(formatMoney(5, 'USD'), '$0.05');
  assert.equal(formatMoney(5, 'GBP'), '£0.05');
});

test('formatMoney with large amount', () => {
  assert.equal(formatMoney(100000000, 'USD'), '$1,000,000.00');
  assert.equal(formatMoney(100000000, 'GBP'), '£1,000,000.00');
});

test('formatMoney with thousands separators', () => {
  assert.equal(formatMoney(1234567, 'USD'), '$12,345.67');
  assert.equal(formatMoney(1234567, 'GBP'), '£12,345.67');
  assert.equal(formatMoney(1234567, 'EUR'), '€12,345.67');
});

test('formatMoney unknown currency defaults to EUR', () => {
  assert.equal(formatMoney(123456, 'XXX'), '€1,234.56');
});

test('formatMoney with single digit cents', () => {
  assert.equal(formatMoney(105, 'USD'), '$1.05');
  assert.equal(formatMoney(105, 'GBP'), '£1.05');
});

test('convert and formatMoney work together', () => {
  const euroCents = 10000;
  const convertResult = convert(euroCents, 'USD');
  assert.equal(convertResult.ok, true);
  const formatted = formatMoney(convertResult.value, 'USD');
  assert(formatted.startsWith('$'));
  assert(formatted.includes('.'));
});

test('convert EUR to all currencies', () => {
  const euroCents = 10000;
  assert.equal(convert(euroCents, 'EUR').ok, true);
  assert.equal(convert(euroCents, 'USD').ok, true);
  assert.equal(convert(euroCents, 'GBP').ok, true);
});

test('convert preserves cent precision', () => {
  const result = convert(12345, 'USD');
  assert.equal(result.ok, true);
  assert(result.value > 0);
  assert(Number.isInteger(result.value));
});

test('formatMoney formats converted amounts correctly', () => {
  const euroCents = 10000;
  const usdCents = convert(euroCents, 'USD').value;
  const formatted = formatMoney(usdCents, 'USD');
  assert(formatted.includes('$'));
  assert(formatted.includes('.'));
  assert(/\$\d+\.\d{2}$/.test(formatted));
});

test('convert does not mutate input', () => {
  const cents = 10000;
  convert(cents, 'USD');
  assert.equal(cents, 10000);
});

test('formatMoney with EUR to USD conversion workflow', () => {
  const invoiceInEUR = 123456;
  const convertedToUSD = convert(invoiceInEUR, 'USD');
  assert.equal(convertedToUSD.ok, true);
  const formatted = formatMoney(convertedToUSD.value, 'USD');
  assert.equal(formatted, '$1,339.51');
});

test('formatMoney with EUR to GBP conversion workflow', () => {
  const invoiceInEUR = 123456;
  const convertedToGBP = convert(invoiceInEUR, 'GBP');
  assert.equal(convertedToGBP.ok, true);
  const formatted = formatMoney(convertedToGBP.value, 'GBP');
  assert.equal(formatted, '£1,040.12');
});

